import{o as e,c as a,j as r,a as o,k as l,g as d,a2 as n}from"./chunks/framework.DDk04jjR.js";const i={align:"center"},s=["src"],c=JSON.parse('{"title":"Blender для початківців","description":"Перші кроки у світі 3D-моделювання в Blender","frontmatter":{"layout":"page","title":"Blender для початківців","description":"Перші кроки у світі 3D-моделювання в Blender"},"headers":[],"relativePath":"blender-basics.md","filePath":"blender-basics.md"}'),h={name:"blender-basics.md"},m=Object.assign(h,{setup(g){return(b,t)=>(e(),a("div",null,[t[0]||(t[0]=r("h1",{id:"🎨-blender-для-початківців",tabindex:"-1"},[o("🎨 Blender для початківців "),r("a",{class:"header-anchor",href:"#🎨-blender-для-початківців","aria-label":'Permalink to "🎨 Blender для початківців"'},"​")],-1)),r("p",i,[r("img",{src:l(d)("/images/Blender_logo_no_text.svg"),alt:"Blender Logo",width:"160"},null,8,s)]),t[1]||(t[1]=n('<h2 id="що-таке-blender" tabindex="-1">Що таке Blender? <a class="header-anchor" href="#що-таке-blender" aria-label="Permalink to &quot;Що таке Blender?&quot;">​</a></h2><p><strong>Blender</strong> — це безкоштовна програма з відкритим кодом для 3D-моделювання, анімації, рендерингу та багато іншого. Вона використовується як професіоналами, так і початківцями по всьому світу.</p><blockquote><p>💡 Blender можна завантажити безкоштовно з офіційного сайту: <strong>blender.org</strong></p></blockquote><hr><h2 id="інтерфеис-blender" tabindex="-1">Інтерфейс Blender <a class="header-anchor" href="#інтерфеис-blender" aria-label="Permalink to &quot;Інтерфейс Blender&quot;">​</a></h2><p>Після запуску Blender ви побачите кілька основних зон:</p><table tabindex="0"><thead><tr><th>Зона</th><th>Призначення</th></tr></thead><tbody><tr><td><strong>3D Viewport</strong></td><td>Головне робоче вікно — тут ви бачите та редагуєте свою сцену</td></tr><tr><td><strong>Outliner</strong></td><td>Список усіх об&#39;єктів на сцені</td></tr><tr><td><strong>Properties</strong></td><td>Налаштування об&#39;єктів, матеріалів, камери, освітлення</td></tr><tr><td><strong>Timeline</strong></td><td>Шкала часу для анімацій</td></tr></tbody></table><hr><h2 id="навігація-у-3d-просторі" tabindex="-1">Навігація у 3D-просторі <a class="header-anchor" href="#навігація-у-3d-просторі" aria-label="Permalink to &quot;Навігація у 3D-просторі&quot;">​</a></h2><h3 id="основні-клавіші" tabindex="-1">Основні клавіші <a class="header-anchor" href="#основні-клавіші" aria-label="Permalink to &quot;Основні клавіші&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Дія</th><th>Клавіша / Комбінація</th></tr></thead><tbody><tr><td>Обертання виду</td><td>Середня кнопка миші (СКМ)</td></tr><tr><td>Переміщення виду</td><td>Shift + СКМ</td></tr><tr><td>Масштабування</td><td>Колесо прокрутки</td></tr><tr><td>Вигляд спереду</td><td>Numpad 1</td></tr><tr><td>Вигляд зверху</td><td>Numpad 7</td></tr><tr><td>Вигляд збоку</td><td>Numpad 3</td></tr><tr><td>Перспектива / Ортогональний</td><td>Numpad 5</td></tr></tbody></table><hr><h2 id="базові-операціі" tabindex="-1">Базові операції <a class="header-anchor" href="#базові-операціі" aria-label="Permalink to &quot;Базові операції&quot;">​</a></h2><h3 id="виділення-об-єктів" tabindex="-1">Виділення об&#39;єктів <a class="header-anchor" href="#виділення-об-єктів" aria-label="Permalink to &quot;Виділення об&#39;єктів&quot;">​</a></h3><ul><li><strong>Лівий клік миші</strong> — виділити об&#39;єкт</li><li><strong>A</strong> — виділити все / зняти виділення</li><li><strong>Shift + клік</strong> — додати до виділення</li></ul><h3 id="трансформаціі" tabindex="-1">Трансформації <a class="header-anchor" href="#трансформаціі" aria-label="Permalink to &quot;Трансформації&quot;">​</a></h3><ul><li><strong>G</strong> — переміщення (Grab)</li><li><strong>R</strong> — обертання (Rotate)</li><li><strong>S</strong> — масштабування (Scale)</li><li><strong>X / Y / Z</strong> — обмеження руху по осі (після натискання G, R або S)</li></ul><h3 id="додавання-об-єктів" tabindex="-1">Додавання об&#39;єктів <a class="header-anchor" href="#додавання-об-єктів" aria-label="Permalink to &quot;Додавання об&#39;єктів&quot;">​</a></h3><ul><li><strong>Shift + A</strong> — відкрити меню додавання об&#39;єктів (Mesh → Cube, Sphere, Cylinder тощо)</li></ul><hr><h2 id="режими-роботи" tabindex="-1">Режими роботи <a class="header-anchor" href="#режими-роботи" aria-label="Permalink to &quot;Режими роботи&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Режим</th><th>Для чого</th></tr></thead><tbody><tr><td><strong>Object Mode</strong></td><td>Робота з об&#39;єктами як цілими одиницями</td></tr><tr><td><strong>Edit Mode</strong> (Tab)</td><td>Редагування вершин, ребер та граней об&#39;єкта</td></tr><tr><td><strong>Sculpt Mode</strong></td><td>Ліпка форми, як з глини</td></tr></tbody></table><hr><h2 id="першии-проєкт-проста-чашка" tabindex="-1">Перший проєкт: проста чашка <a class="header-anchor" href="#першии-проєкт-проста-чашка" aria-label="Permalink to &quot;Перший проєкт: проста чашка&quot;">​</a></h2><h3 id="крок-1-—-створіть-циліндр" tabindex="-1">Крок 1 — Створіть циліндр <a class="header-anchor" href="#крок-1-—-створіть-циліндр" aria-label="Permalink to &quot;Крок 1 — Створіть циліндр&quot;">​</a></h3><ol><li>Видаліть куб за замовчуванням (виділіть → <strong>X</strong> → Delete)</li><li><strong>Shift + A</strong> → Mesh → <strong>Cylinder</strong></li><li>У нижньому лівому куті налаштуйте: Vertices: <strong>32</strong>, Radius: <strong>1</strong>, Depth: <strong>1.5</strong></li></ol><h3 id="крок-2-—-увіидіть-в-edit-mode" tabindex="-1">Крок 2 — Увійдіть в Edit Mode <a class="header-anchor" href="#крок-2-—-увіидіть-в-edit-mode" aria-label="Permalink to &quot;Крок 2 — Увійдіть в Edit Mode&quot;">​</a></h3><ol><li>Натисніть <strong>Tab</strong> для переходу в Edit Mode</li><li>Виділіть верхню грань (<strong>Alt + клік</strong> на верхньому ребрі)</li><li><strong>I</strong> (Inset) — створіть внутрішню грань</li><li><strong>E</strong> (Extrude) + <strong>S</strong> — видавіть вниз для створення порожнини</li></ol><h3 id="крок-3-—-додаите-ручку" tabindex="-1">Крок 3 — Додайте ручку <a class="header-anchor" href="#крок-3-—-додаите-ручку" aria-label="Permalink to &quot;Крок 3 — Додайте ручку&quot;">​</a></h3><ol><li>Поверніться в Object Mode (<strong>Tab</strong>)</li><li><strong>Shift + A</strong> → Mesh → <strong>Torus</strong> (для ручки)</li><li>Масштабуйте та розмістіть тор збоку циліндра</li></ol><hr><h2 id="корисні-поради" tabindex="-1">Корисні поради <a class="header-anchor" href="#корисні-поради" aria-label="Permalink to &quot;Корисні поради&quot;">​</a></h2><ul><li>🔄 <strong>Ctrl + Z</strong> — скасувати дію</li><li>💾 <strong>Ctrl + S</strong> — зберегти файл</li><li>📷 <strong>Numpad 0</strong> — переглянути через камеру</li><li>🎯 <strong>Numpad .</strong> — сфокусуватися на виділеному об&#39;єкті</li></ul><hr><h2 id="що-далі" tabindex="-1">Що далі? <a class="header-anchor" href="#що-далі" aria-label="Permalink to &quot;Що далі?&quot;">​</a></h2><p>Після опанування базових інструментів рекомендуємо:</p><ul><li>Вивчити <strong>модифікатори</strong> (Subdivision Surface, Mirror, Boolean)</li><li>Спробувати <strong>UV-розгортку</strong> та <strong>текстурування</strong></li><li>Познайомитися з <strong>матеріалами та шейдерами</strong></li><li>Спробувати <strong>рендеринг</strong> у Cycles або EEVEE</li></ul>',37))]))}});export{c as __pageData,m as default};
